#!/bin/bash
# Installs (or removes) a weekly launchd job that writes an improve-system report without building anything.
#
# Usage: bash install-macos.sh [--weekday 1] [--hour 9] [--minute 0] [--days 7] [--run-now] [--uninstall] [--dry-run]
#   --weekday  0 or 7 = Sunday, 1 = Monday ... 6 = Saturday (default: 1)
#   --run-now  starts a run right after installing, to test it
#   --dry-run  prints the generated files without installing anything
set -euo pipefail

LABEL="com.improve-system.weekly"
WEEKDAY=1 HOUR=9 MINUTE=0 DAYS=7 RUN_NOW=0 UNINSTALL=0 DRY_RUN=0
die() { echo "Error: $*" >&2; exit 2; }
int_in() { [[ "$1" =~ ^[0-9]+$ ]] && (( 10#$1 >= $2 && 10#$1 <= $3 )); }

while (($#)); do
  case "$1" in
    --weekday) WEEKDAY="${2:-}"; shift 2 ;;
    --hour) HOUR="${2:-}"; shift 2 ;;
    --minute) MINUTE="${2:-}"; shift 2 ;;
    --days) DAYS="${2:-}"; shift 2 ;;
    --run-now) RUN_NOW=1; shift ;;
    --uninstall) UNINSTALL=1; shift ;;
    --dry-run) DRY_RUN=1; shift ;;
    -h|--help) sed -n '2,8p' "$0"; exit 0 ;;
    *) die "unknown option: $1" ;;
  esac
done
int_in "$WEEKDAY" 0 7 || die "--weekday must be between 0 and 7"
int_in "$HOUR" 0 23 || die "--hour must be between 0 and 23"
int_in "$MINUTE" 0 59 || die "--minute must be between 0 and 59"
int_in "$DAYS" 1 90 || die "--days must be between 1 and 90"

STATE="$HOME/.claude/improve-system"
PLIST="$HOME/Library/LaunchAgents/$LABEL.plist"
WRAPPER="$STATE/bin/weekly.sh"
SKILL_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
DIGEST="$SKILL_DIR/scripts/digest.mjs"
DOMAIN="gui/$(id -u)"

if ((UNINSTALL)); then
  launchctl bootout "$DOMAIN/$LABEL" 2>/dev/null || true
  rm -f "$PLIST" "$WRAPPER"
  echo "Weekly job removed. Reports and logs kept in $STATE."
  exit 0
fi

if ((!DRY_RUN)); then
  [[ "$(uname -s)" == "Darwin" ]] || die "this script is for macOS"
fi
[[ -f "$DIGEST" ]] || die "digest.mjs not found next to this script ($DIGEST)"
CLAUDE_BIN="$(command -v claude || true)"
NODE_BIN="$(command -v node || true)"
if ((!DRY_RUN)); then
  [[ -n "$CLAUDE_BIN" ]] || die "claude command not found in PATH"
  [[ -n "$NODE_BIN" ]] || die "node command not found in PATH"
fi
CLAUDE_BIN="${CLAUDE_BIN:-/usr/local/bin/claude}"
NODE_BIN="${NODE_BIN:-/usr/local/bin/node}"
# launchd starts with a minimal PATH: keep the folders where claude and node live today.
RUN_PATH="$(dirname "$CLAUDE_BIN"):$(dirname "$NODE_BIN"):/usr/bin:/bin:/usr/sbin:/sbin"

# Only what a report needs: run this digest script, read, and write reports. Nothing else is allowed,
# so the scheduled run cannot touch CLAUDE.md, settings.json or skills.
ALLOWED="Bash(node $DIGEST:*) Read Grep Glob Write(~/.claude/improve-system/reports/**) Edit(~/.claude/improve-system/reports/**)"

wrapper_content() {
  cat <<WRAP
#!/bin/bash
# Generated by install-macos.sh ($LABEL). Writes a report, builds nothing.
set -u
export PATH="$RUN_PATH"
STATE="$STATE"
mkdir -p "\$STATE/logs" "\$STATE/reports"
LOG="\$STATE/logs/\$(date +%F).log"
# Private temp folder for this run only: the digest lands here and is deleted below, whatever happens.
export TMPDIR="\$(mktemp -d "\$STATE/run.XXXXXX")"
trap 'rm -rf "\$TMPDIR"' EXIT
cd "\$STATE" || exit 1
notify() { osascript -e "display notification \"\$1\" with title \"Improve System\"" >/dev/null 2>&1 || true; }
echo "== \$(date): /improve-system $DAYS auto" >>"\$LOG"
if "$CLAUDE_BIN" -p "/improve-system $DAYS auto" --allowedTools "$ALLOWED" >>"\$LOG" 2>&1; then
  notify "Weekly report ready. Type /improve-system to pick what to build."
else
  notify "Weekly report failed, see \$LOG"
  exit 1
fi
# Keep 12 weeks of logs.
find "\$STATE/logs" -name '*.log' -mtime +84 -delete 2>/dev/null || true
WRAP
}

plist_content() {
  cat <<PL
<?xml version="1.0" encoding="UTF-8"?>
<!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" "http://www.apple.com/DTDs/PropertyList-1.0.dtd">
<plist version="1.0">
<dict>
  <key>Label</key><string>$LABEL</string>
  <key>ProgramArguments</key>
  <array><string>/bin/bash</string><string>$WRAPPER</string></array>
  <key>StartCalendarInterval</key>
  <dict>
    <key>Weekday</key><integer>$((10#$WEEKDAY))</integer>
    <key>Hour</key><integer>$((10#$HOUR))</integer>
    <key>Minute</key><integer>$((10#$MINUTE))</integer>
  </dict>
  <key>StandardOutPath</key><string>$STATE/logs/launchd.log</string>
  <key>StandardErrorPath</key><string>$STATE/logs/launchd.log</string>
  <key>ProcessType</key><string>Background</string>
  <key>LowPriorityIO</key><true/>
</dict>
</plist>
PL
}

if ((DRY_RUN)); then
  echo "### $WRAPPER"; wrapper_content
  echo "### $PLIST"; plist_content
  exit 0
fi

mkdir -p "$STATE/bin" "$STATE/logs" "$STATE/reports" "$(dirname "$PLIST")"
chmod 700 "$STATE"
wrapper_content >"$WRAPPER"
chmod 700 "$WRAPPER"
plist_content >"$PLIST"
plutil -lint "$PLIST" >/dev/null
launchctl bootout "$DOMAIN/$LABEL" 2>/dev/null || true
launchctl bootstrap "$DOMAIN" "$PLIST"

DAY_NAMES=(Sunday Monday Tuesday Wednesday Thursday Friday Saturday Sunday)
printf 'Installed: every %s at %02d:%02d, over the last %s days.\n' "${DAY_NAMES[$((10#$WEEKDAY))]}" "$((10#$HOUR))" "$((10#$MINUTE))" "$DAYS"
echo "Reports: $STATE/reports/   Logs: $STATE/logs/"
echo "If the Mac is asleep at that time, the job runs on wake; if it is off, that week is skipped."
if ((RUN_NOW)); then
  launchctl kickstart -k "$DOMAIN/$LABEL"
  echo "Test run started: a notification arrives when the report is ready (a few minutes)."
fi
